// 解码只读取明确选择和独立原件，不从旧 Shop1 推算或补写已经经过的租期。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "private_shop_daily_rent_codec.hpp"
#include "resident/domains/local_economy/economic_payload_guard.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
namespace hanmo::resident {namespace {
Status catalog_valid(const PrivateShopDailyRentCatalog& c){return c.version==1&&c.profile=="opening_anchored_two_halfdays_v1"&&c.arrears_policy=="one_unpaid_period_then_suspend_v1"?common_success():common_failure("PrivateShopDailyRentProfileMismatch");}
bool kind(const StableId& k){return k==private_shop_rent_assessed_kind||k==private_shop_rent_paid_kind||k==private_shop_rent_resumed_kind;}
}
Outcome<PrivateShopDailyRentCatalog> decode_private_shop_daily_rent_catalog(const BoundaryValue& value){auto unique=validate_economic_payload_fields(value);if(!unique.ok)return {false,{},unique.error};try{PrivateShopDailyRentCatalog out;dynamic_economy_codec::decode(value,out,private_shop_daily_rent_module);auto valid=catalog_valid(out);if(!valid.ok)return {false,{},valid.error};return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<std::optional<PrivateShopDailyRentCatalog>> decode_private_shop_daily_rent_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){const auto* dynamic=scenario.find("dynamic_world");const auto* block=dynamic?dynamic->find(private_shop_daily_rent_module):nullptr;if(!block)return {true,std::nullopt,{}};auto unique=validate_economic_payload_fields(*dynamic);if(!unique.ok)return {false,{},unique.error};try{if(boundary::get_string(*dynamic,"profile","dynamic_world")!="local_society_v1"||std::find(caps.begin(),caps.end(),private_shop_daily_rent_capability)==caps.end())return {false,{},common_failure("PrivateShopDailyRentProfileRequired").error};auto shops=decode_private_shop_profile(scenario,caps);if(!shops.ok)return {false,{},shops.error};if(!shops.value)return {false,{},common_failure("PrivateShopDailyRentShopsRequired").error};auto value=decode_private_shop_daily_rent_catalog(*block);if(!value.ok)return {false,{},value.error};return {true,std::optional<PrivateShopDailyRentCatalog>{std::move(value.value)},{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<PrivateShopDailyRentState> decode_private_shop_daily_rent_state(const BoundaryValue& value){auto unique=validate_economic_payload_fields(value);if(!unique.ok)return {false,{},unique.error};try{PrivateShopDailyRentState out;dynamic_economy_codec::decode(value,out,private_shop_daily_rent_module);if(out.version!=1)boundary::fail("UnsupportedPrivateShopDailyRentVersion",private_shop_daily_rent_module);return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status emit_private_shop_daily_rent_state_fields(ProjectionWriter& writer,const PrivateShopDailyRentState& s){try{if(s.version!=1)boundary::fail("UnsupportedPrivateShopDailyRentVersion",private_shop_daily_rent_module);return dynamic_economy_codec::emit_fields(writer,s);}catch(const boundary::DecodeFailure&failure){return writer.reject(failure.error.original.code,failure.error.original.path);}}
BoundaryValue encode_private_shop_daily_rent_state(const PrivateShopDailyRentState& s){BoundaryValue out;BoundaryProjectionWriter writer(out);auto valid=writer.object("",[&](auto&fields){return emit_private_shop_daily_rent_state_fields(fields,s);});if(valid.ok)valid=writer.finish();if(!valid.ok)throw boundary::DecodeFailure{valid.error};return out;}
Status visit_private_shop_daily_rent_checkpoint(CodecVisitor& v,PrivateShopDailyRentState& s){if(!v.reading()&&s.version!=1)return v.reject("UnsupportedPrivateShopDailyRentVersion",private_shop_daily_rent_module);auto result=dynamic_economy_codec::checkpoint(v,private_shop_daily_rent_module,s);if(!result.ok)return result;return s.version==1?v.status():v.reject("UnsupportedPrivateShopDailyRentVersion",private_shop_daily_rent_module);}
Status validate_private_shop_daily_rent_layout(const CommonStore& c,const PrivateShopDailyRentState* s){
 if(s&&s->version!=1)return common_failure("UnsupportedPrivateShopDailyRentVersion");
 auto check=[&](const auto& table,const StableId& k)->Status{for(const auto& row:table.rows()){const auto n=organization_instance_sequence(row.first,k);const auto* h=c.state().facts.find(row.first);if(row.first!=row.second.id||!n||*n>=c.state().next_instance_id||!h||h->id!=row.first||h->kind!=k||h->domain!=private_shop_daily_rent_module)return common_failure("PrivateShopDailyRentFactMismatch",row.first);}return common_success();};
 if(s){auto v=check(s->assessments,private_shop_rent_assessed_kind);if(!v.ok)return v;v=check(s->payments,private_shop_rent_paid_kind);if(!v.ok)return v;v=check(s->resumptions,private_shop_rent_resumed_kind);if(!v.ok)return v;}
 for(const auto& row:c.state().facts.rows())if(row.second.domain==private_shop_daily_rent_module||kind(row.second.kind))if(!s||row.first!=row.second.id||row.second.domain!=private_shop_daily_rent_module||!kind(row.second.kind)||!(row.second.kind==private_shop_rent_assessed_kind?s->assessments.find(row.first)!=nullptr:row.second.kind==private_shop_rent_paid_kind?s->payments.find(row.first)!=nullptr:s->resumptions.find(row.first)!=nullptr))return common_failure("PrivateShopDailyRentOrphanFact",row.first);
 return common_success();
}
Status emit_private_shop_daily_rent_fact_payload_fields(ProjectionWriter& writer,const CommonStore& c,const PrivateShopDailyRentState& s,const FactRecord& h){
 auto valid=validate_private_shop_daily_rent_layout(c,&s);if(!valid.ok)return valid;const auto* actual=c.state().facts.find(h.id);
 if(!actual||actual->id!=h.id||actual->kind!=h.kind||actual->domain!=h.domain||h.domain!=private_shop_daily_rent_module)return writer.reject("PrivateShopDailyRentFactMismatch",h.id);
 if(h.kind==private_shop_rent_assessed_kind){if(const auto* x=s.assessments.find(h.id))return dynamic_economy_codec::emit_fields(writer,*x);}
 else if(h.kind==private_shop_rent_paid_kind){if(const auto* x=s.payments.find(h.id))return dynamic_economy_codec::emit_fields(writer,*x);}
 else if(h.kind==private_shop_rent_resumed_kind){if(const auto* x=s.resumptions.find(h.id))return dynamic_economy_codec::emit_fields(writer,*x);}
 return writer.reject("PrivateShopDailyRentFactMismatch",h.id);
}
Status validate_private_shop_daily_rent_fact_payload(ProjectionWriter& writer,const CommonStore& c,const PrivateShopDailyRentState& s,const FactRecord& h){return writer.validate_detached([&](auto& out){return emit_private_shop_daily_rent_fact_payload_fields(out,c,s,h);});}
Outcome<BoundaryValue> encode_private_shop_daily_rent_fact_payload(const CommonStore& c,const PrivateShopDailyRentState& s,const FactRecord& h){BoundaryValue out;BoundaryProjectionWriter writer(out);auto valid=writer.object("",[&](auto& fields){return emit_private_shop_daily_rent_fact_payload_fields(fields,c,s,h);});if(valid.ok)valid=writer.finish();if(!valid.ok)return {false,{},valid.error};return {true,std::move(out),{}};}

}
